int main() {
    int t;
    cin>>t;
    for(int i=0;i<t;i++){
        int n;
        cin>>n;
        vector<ll>arr(n);
        for(ll &x : arr){
            cin>>x;
        }
        vector<ll>in(n,0);
        vector<ll>hei(n,0);
        if(n>1)
        in[1]=1;
        for(int i=2;i<n;i++){
            in[i]=mod-(mod/i)*in[mod%i]%mod;
        }
        for(int i=1;i<n;i++){
            hei[i]=(hei[i-1]+in[i])%mod;
        }
        ll result=0;
        for(int i=0;i<n;i++){
            ll coe=(hei[i]+hei[n-1-i])%mod;
            result=(result+arr[i]*coe)%mod;
        }
        cout<<result<<'\n';
    }
    return 0;
}
